_BOOK_CACHE: list[Path] = []


def _book_dir() -> Path:
    """The agent's /app/data, rebuilt here: the verifier container never has it."""
    if not _BOOK_CACHE:
        root = Path(tempfile.mkdtemp(prefix="shipped-meter-book-"))
        for rel, packed in _SHIPPED_BOOK.items():
            target = root / rel
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(zlib.decompress(base64.b64decode(packed)))
        _BOOK_CACHE.append(root)
    return _BOOK_CACHE[0]


def _root_only_tests_present() -> bool:
    try:
        status = Path("/tests").stat()
    except FileNotFoundError:
        return False
    return status.st_uid == 0 and (status.st_mode & 0o077) == 0


def _untrusted_command(command: list[str]) -> list[str]:
    if os.name != "posix" and _root_only_tests_present():
        raise RuntimeError("verifier isolation requires POSIX uid/gid dropping")
    if os.name == "posix" and os.geteuid() != 0 and _root_only_tests_present():
        raise RuntimeError("verifier must run as root to isolate submitted code from /tests")
    if os.name == "posix" and os.geteuid() == 0:
        return [*_SETPRIV, *command]
    return command


class _Dropped(Exception):
    pass


def _trim(value: object) -> str:
    return "" if value is None else str(value).strip()


def _fold(value: object) -> str:
    return _trim(value).lower()


def _grid(path: Path, sep: str = ",") -> list[dict[str, str]]:
    with path.open(encoding="utf-8", newline="") as fh:
        return [dict(row) for row in csv.DictReader(fh, delimiter=sep)]


def _whole(value: object) -> int:
    text = _trim(value)
    if not text or not text.isascii() or not text.isdigit():
        raise _Dropped("units_consumed")
    return int(text)


def _clock(value: object) -> datetime:
    text = _trim(value)
    if text.endswith("Z"):
        text = text[:-1]
    stem, _, rest = text.partition("T")
    try:
        yy, mm, dd = (int(piece) for piece in stem.split("-"))
        hh, mi, ss = (int(piece) for piece in rest.split(":"))
        return datetime(yy, mm, dd, hh, mi, ss)
    except (TypeError, ValueError) as exc:
        raise _Dropped("read_ts") from exc


def _num(value: object) -> Decimal:
    try:
        return Decimal(_trim(value))
    except ArithmeticError as exc:
        raise _Dropped("amount") from exc


class _Vault:
    def __init__(self, folder: Path) -> None:
        rules = configparser.ConfigParser()
        rules.read_string((folder / "policy.ini").read_text(encoding="utf-8"))
        self.floor = {name.split("_")[1]: int(text)
                      for name, text in rules["disconnection"].items()}
        self.open_day = _trim(rules["wallet"]["opening_rate_date"])
        self.mode = ROUND_BY_NAME[_fold(rules["rounding"]["mode"])]
        self.litre = Decimal(_trim(rules["volume"]["litres_per_kilolitre"]))
        self.gap_label = _trim(rules["labels"]["unassigned_cycle"])
        self.levy_label = _fold(rules["labels"]["levy_route_group"])

        self.holder: dict[str, dict[str, str]] = {}
        newest: dict[str, tuple[str, int]] = {}
        for seat, row in enumerate(_grid(folder / "accounts.csv")):
            who = _trim(row["account_id"])
            mark = (_trim(row["revised_at"]), seat)
            if who in newest and newest[who] > mark:
                continue
            newest[who] = mark
            self.holder[who] = {
                "tariff_class": _fold(row["tariff_class"]),
                "service_postcode": _trim(row["service_postcode"]),
                "opening_credit_minor": _trim(row["opening_credit_minor"]),
                "opening_currency": _trim(row["opening_currency"]).upper(),
            }

        self.stem: dict[str, tuple[str, str]] = {}
        self.over: dict[str, str] = {}
        for row in _grid(folder / "service_zones.csv"):
            node = _fold(row["zone"])
            self.stem[_trim(row["postcode_prefix"])] = (
                node, _trim(row["default_currency"]).upper())
            self.over[node] = _fold(row["parent_zone"])

        self.category: dict[str, str] = {}
        self.unit_volume_litres: dict[str, Decimal] = {}
        for row in _grid(folder / "tariff_catalogue.csv"):
            code = _trim(row["tariff_code"])
            self.category[code] = _fold(row["category"])
            self.unit_volume_litres[code] = Decimal(_trim(row["unit_volume_litres"]))

        self.route = {_fold(row["collector"]): _fold(row["route_group"])
                      for row in _grid(folder / "collectors.csv")}

        self.site_postcode: dict[str, str] = {}
        self.site_shift: dict[str, int] = {}
        self.installed_litres: dict[str, int] = {}
        self.service_floor_litres: dict[str, int] = {}
        self.uncatalogued_capacity_litres = 0
        for row in _grid(folder / "meter_sites.csv"):
            site = _trim(row["meter_site"])
            self.site_postcode[site] = _trim(row["postcode"])
            self.site_shift[site] = int(_trim(row["utc_offset_minutes"]))
            code = _trim(row["tariff_code"])
            self.installed_litres[code] = (self.installed_litres.get(code, 0)
                                           + int(_trim(row["installed_litres"])))
            self.service_floor_litres[code] = (self.service_floor_litres.get(code, 0)
                                               + int(_trim(row["service_floor_litres"])))
        for code, litres in self.installed_litres.items():
            if code not in self.category:
                self.uncatalogued_capacity_litres += litres

        self.usd_rate: dict[tuple[str, str], Decimal] = {}
        self.rate_days: dict[str, list[str]] = {}
        for row in _grid(folder / "currency_rates.csv"):
            when = _trim(row["rate_date"])
            money = _trim(row["currency"]).upper()
            self.usd_rate[(when, money)] = Decimal(_trim(row["usd_rate"]))
            self.rate_days.setdefault(money, []).append(when)
        for money in self.rate_days:
            self.rate_days[money].sort()

        almanac = json.loads((folder / "billing_calendar.json").read_text(encoding="utf-8"))
        self.cycles = sorted((_trim(c["opens"]), _trim(c["closes"]), _trim(c["cycle"]))
                             for c in almanac["cycles"])

    def top_zone(self, node: str) -> str:
        chain: set[str] = set()
        while self.over.get(node) and node not in chain:
            chain.add(node)
            node = self.over[node]
        return node

    def quote(self, when: str, money: str) -> tuple[Decimal, bool]:
        here = self.usd_rate.get((when, money))
        if here is not None:
            return here, False
        curve = self.rate_days.get(money, [])
        cut = bisect.bisect_left(curve, when)
        if cut == 0:
            raise _Dropped("usd_rate")
        return self.usd_rate[(curve[cut - 1], money)], True

    def cycle_of(self, when: str) -> str:
        for opens, closes, name in self.cycles:
            if opens <= when <= closes:
                return name
        return self.gap_label

    def to_cents(self, gross: Decimal, rate: Decimal) -> tuple[int, Decimal]:
        raw = gross * rate * 100
        return int(raw.quantize(Decimal(1), rounding=self.mode)), raw

    def opening(self, who: str) -> int:
        seat = self.holder[who]
        rate, _carried = self.quote(self.open_day, seat["opening_currency"])
        value, _raw = self.to_cents(Decimal(seat["opening_credit_minor"]) / 100, rate)
        return value


def _fix_table(folder: Path) -> dict[tuple[str, str], str]:
    champion: dict[tuple[str, str], tuple[tuple[str, int], str]] = {}
    text = (folder / "amendments.log").read_text(encoding="utf-8")
    for seat, line in enumerate(text.splitlines()):
        word = line.split()
        if len(word) < 3 or word[2] != "amendment":
            continue
        pairs = dict(token.partition("=")[::2] for token in word[3:])
        if "target" not in pairs or "field" not in pairs:
            continue
        slot = (pairs["target"], pairs["field"])
        mark = (word[0], seat)
        if slot not in champion or mark > champion[slot][0]:
            champion[slot] = (mark, pairs.get("value", ""))
    return {slot: payload for slot, (_mark, payload) in champion.items()}


def _lines(folder: Path) -> list[tuple[str, dict]]:
    out: list[tuple[str, dict]] = []
    if (folder / "consumption.csv").is_file():
        out += [("consumption.csv", row) for row in _grid(folder / "consumption.csv")]
    if (folder / "remittances.tsv").is_file():
        out += [("remittances.tsv", row) for row in _grid(folder / "remittances.tsv", "\t")]
    if (folder / "levies.jsonl").is_file():
        for line in (folder / "levies.jsonl").read_text(encoding="utf-8").splitlines():
            if not line.strip():
                continue
            try:
                out.append(("levies.jsonl", json.loads(line)))
            except ValueError:
                out.append(("levies.jsonl", {}))
    if (folder / "legacy_reads.txt").is_file():
        for line in (folder / "legacy_reads.txt").read_text(encoding="latin-1").splitlines():
            if not line.strip() or line.lstrip().startswith("#"):
                continue
            cell = [piece.strip() for piece in line.split("|")]
            out.append(("legacy_reads.txt",
                        dict(zip(PIPE_KEYS, cell)) if len(cell) == 11 else {}))
    return out


def _signed(origin: str, raw: dict) -> tuple[str, int, Decimal]:
    if origin == "consumption.csv":
        units = _whole(raw.get("units_consumed"))
        return "consumption", units, -(_num(raw.get("rate_per_unit")) * units)
    if origin == "remittances.tsv":
        units = _whole(raw.get("units_consumed"))
        return "remittance", units, abs(_num(raw.get("remit_amount")))
    if origin == "levies.jsonl":
        tag = _fold(raw.get("kind"))
        if tag not in ("surcharge", "rebate"):
            raise _Dropped("kind")
        minor = raw.get("amount_minor")
        if isinstance(minor, bool) or not isinstance(minor, int):
            raise _Dropped("amount_minor")
        return tag, 0, Decimal(minor) / 100
    tag = _fold(raw.get("kind"))
    if tag not in PIPE_SIGN:
        raise _Dropped("kind")
    units = _whole(raw.get("units_consumed"))
    return tag, units, abs(_num(raw.get("amount"))) * PIPE_SIGN[tag]


def _project(origin: str, raw: dict, vault: _Vault) -> tuple[dict, tuple[bool, bool, bool]]:
    who = _trim(raw.get("account_id"))
    code = _trim(raw.get("tariff_code"))
    if who not in vault.holder:
        raise _Dropped("account_id")
    if code not in vault.category:
        raise _Dropped("tariff_code")
    seat = vault.holder[who]
    if origin == "levies.jsonl":
        postcode, site, shift = seat["service_postcode"], None, 0
        lane = vault.levy_label
    else:
        site = _trim(raw.get("meter_site"))
        if site not in vault.site_postcode:
            raise _Dropped("meter_site")
        postcode, shift = vault.site_postcode[site], vault.site_shift[site]
        wire = _fold(raw.get("collector"))
        if wire not in vault.route:
            raise _Dropped("collector")
        lane = vault.route[wire]
    head = postcode.partition("-")[0].strip()
    if head not in vault.stem:
        raise _Dropped("postcode_prefix")
    leaf, backup = vault.stem[head]
    money = _trim(raw.get("currency")).upper() or backup
    local = _clock(raw.get("read_ts"))
    utc = local - timedelta(minutes=shift)
    when = utc.date().isoformat()
    rate, carried = vault.quote(when, money)
    kind, units, gross = _signed(origin, raw)
    cents, product = vault.to_cents(gross, rate)
    doubled = product * 2
    record = {
        "reading_id": _trim(raw.get("reading_id")),
        "posting_date": when,
        "utc_instant": utc.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "billing_cycle": vault.cycle_of(when),
        "account_id": who,
        "tariff_class": seat["tariff_class"],
        "zone": vault.top_zone(leaf),
        "tariff_code": code,
        "category": vault.category[code],
        "kind": kind,
        "units": units,
        "posted_usd_cents": cents,
        "currency": money,
        "source": origin,
        "route_group": lane,
        "meter_site": site,
    }
    flags = (carried, utc.date() != local.date(),
             doubled == doubled.to_integral_value() and int(doubled) % 2 != 0)
    return record, flags


def _units(record: dict) -> int:
    return NET_SIGN.get(record["kind"], 0) * record["units"]


def _sum_by(records: list[dict], field: str) -> dict[str, int]:
    pot: dict[str, int] = {}
    for record in records:
        pot[record[field]] = pot.get(record[field], 0) + record["posted_usd_cents"]
    return dict(sorted(pot.items()))


def _slice(taken: list[dict], barred: list[dict], field: str, name: str,
           extra: dict | None = None) -> dict:
    mine = [r for r in taken if r[field] == name]
    payload = {
        field: name,
        "event_count": len(mine),
        "total_usd_cents": sum(r["posted_usd_cents"] for r in mine),
        "net_units": sum(_units(r) for r in mine),
        "held_count": sum(1 for r in barred if r[field] == name),
        "accounts": sorted({r["account_id"] for r in mine}),
        "by_kind": _sum_by(mine, "kind"),
        "by_category": _sum_by(mine, "category"),
    }
    if extra:
        payload.update(extra)
    return payload


def _post(folder: Path) -> tuple[dict, types.SimpleNamespace]:
    vault = _Vault(folder)
    fixes = _fix_table(folder)
    rows = _lines(folder)
    live = [name for name in FEED_ORDER if (folder / name).is_file()]
    charge_ids = {_trim(raw.get("reading_id")) for origin, raw in rows
                  if origin == "consumption.csv"}
    seen_ids = {_trim(raw.get("reading_id")) for _origin, raw in rows
                if _trim(raw.get("reading_id"))}
    unmatched = sorted({slot for slot, _field in fixes if slot not in seen_ids})

    standing: list[dict] = []
    orphans: list[str] = []
    dropped = {name: 0 for name in live}
    bad_charges: set[str] = set()
    touched: set[str] = set()
    link_of: dict[int, str] = {}
    flag_of: dict[int, tuple[bool, bool, bool]] = {}
    for origin, raw in rows:
        ident = _trim(raw.get("reading_id"))
        edited = dict(raw)
        for field in PATCHABLE[origin]:
            if (ident, field) in fixes:
                edited[field] = fixes[(ident, field)]
                touched.add(ident)
        if origin == "remittances.tsv":
            link = _trim(edited.get("charge_reading_id"))
            if link and link not in charge_ids:
                orphans.append(ident)
                continue
        try:
            record, flags = _project(origin, edited, vault)
        except (_Dropped, ArithmeticError, ValueError, TypeError, AttributeError, KeyError):
            dropped[origin] += 1
            if origin == "consumption.csv":
                bad_charges.add(ident)
            continue
        standing.append(record)
        flag_of[id(record)] = flags
        link_of[id(record)] = (_trim(edited.get("charge_reading_id"))
                               if origin == "remittances.tsv" else "")

    queue: dict[str, list[dict]] = {}
    for record in standing:
        queue.setdefault(record["account_id"], []).append(record)
    taken: list[dict] = []
    barred: list[dict] = []
    closing = 0
    for who in vault.holder:
        wallet = vault.opening(who)
        limit = vault.floor[vault.holder[who]["tariff_class"]]
        for record in sorted(queue.get(who, []),
                             key=lambda item: (item["utc_instant"], item["reading_id"])):
            value = record["posted_usd_cents"]
            if value < 0 and wallet + value < limit:
                barred.append(record)
                continue
            wallet += value
            taken.append(record)
        closing += wallet

    carried_ids = sorted(r["reading_id"] for r in taken if flag_of[id(r)][0])
    shifted_ids = sorted(r["reading_id"] for r in taken if flag_of[id(r)][1])
    halved_ids = sorted(r["reading_id"] for r in taken if flag_of[id(r)][2])
    stale_ids = sorted(r["reading_id"] for r in taken
                       if link_of[id(r)] and link_of[id(r)] in bad_charges)

    taken.sort(key=lambda record: record["reading_id"])
    skipped_total = sum(dropped.values())
    overview: dict[str, object] = {
        "event_count": len(taken),
        "skipped_count": skipped_total,
        "held_count": len(barred),
        "orphan_remittance_count": len(orphans),
        "total_usd_cents": sum(r["posted_usd_cents"] for r in taken),
        "net_units": sum(_units(r) for r in taken),
        "wallet_closing_usd_cents": closing,
    }
    for field in ("zone", "tariff_class", "kind", "category", "route_group",
                  "billing_cycle", "source"):
        overview["by_" + field] = _sum_by(taken, field)

    per_feed: dict[str, int] = {}
    for record in taken:
        per_feed[record["source"]] = per_feed.get(record["source"], 0) + 1
    barred_feed = {name: 0 for name in live}
    for record in barred:
        barred_feed[record["source"]] += 1

    by_code: dict[str, list[dict]] = {}
    for record in taken:
        by_code.setdefault(record["tariff_code"], []).append(record)
    shelf = []
    for code in sorted(vault.category):
        mine = by_code.get(code, [])
        net = sum(_units(r) for r in mine)
        volume = Decimal(net) * vault.unit_volume_litres[code] * vault.litre
        shelf.append({
            "tariff_code": code,
            "category": vault.category[code],
            "event_count": len(mine),
            "total_usd_cents": sum(r["posted_usd_cents"] for r in mine),
            "net_units": net,
            "installed_litres": vault.installed_litres.get(code, 0),
            "service_floor_litres": vault.service_floor_litres.get(code, 0),
            "net_volume_litres": int(volume.quantize(Decimal(1), rounding=vault.mode)),
        })

    payloads: dict[str, object] = {
        "normalized.jsonl": taken,
        "summary.json": overview,
        "data_quality.json": {
            "input_files": sorted(entry.name for entry in folder.iterdir() if entry.is_file()),
            "records_by_source": dict(sorted(per_feed.items())),
            "skipped_by_source": dict(sorted(dropped.items())),
            "held_by_source": dict(sorted(barred_feed.items())),
            "skipped_count": skipped_total,
            "held_count": len(barred),
            "orphan_remittance_count": len(orphans),
            "held_reading_ids": sorted({r["reading_id"] for r in barred}),
            "orphan_remittance_ids": sorted(set(orphans)),
            "unmatched_amendment_targets": unmatched,
        },
        "product_summary.json": {"tariffs": shelf},
    }
    for name in ZONE_FILES:
        payloads[f"region_{name}.json"] = _slice(taken, barred, "zone", name)
    for name in CLASS_FILES:
        payloads[f"segment_{name}.json"] = _slice(
            taken, barred, "tariff_class", name,
            {"disconnection_floor_usd_cents": vault.floor[name]})

    facts = types.SimpleNamespace(**{
        "held_reading_ids": sorted({r["reading_id"] for r in barred}),
        "held_value_usd_cents": sum(r["posted_usd_cents"] for r in barred),
        "held_accounts": len({r["account_id"] for r in barred}),
        "orphan_remittance_ids": sorted(set(orphans)),
        "unmatched_amendment_targets": unmatched,
        "carry_back_rate_events": carried_ids,
        "day_shift_events": shifted_ids,
        "half_cent_events": halved_ids,
        "stale_link_remittances": stale_ids,
        # The posted subset, so a row check can look each id up in the stream. The
        # contract's amended_readings closing figure counts every amended id.
        "amended_posted_readings": sorted(touched & {r["reading_id"] for r in taken}),
        "underfunded_accounts": sum(1 for who, seat in vault.holder.items()
                                    if vault.opening(who) < vault.floor[seat["tariff_class"]]),
        "uncatalogued_capacity_litres": vault.uncatalogued_capacity_litres,
        "cents_by_reading": {r["reading_id"]: r["posted_usd_cents"] for r in taken},
        "class_by_reading": {r["reading_id"]: r["tariff_class"] for r in taken},
        "currency_by_reading": {r["reading_id"]: r["currency"] for r in taken},
        "units_by_reading": {r["reading_id"]: r["units"] for r in taken},
        "cycle_by_reading": {r["reading_id"]: [r["posting_date"], r["utc_instant"],
                                               r["billing_cycle"]] for r in taken},
    })
    return payloads, facts


_TRUTH_CACHE: dict[tuple[str, float], tuple[dict, types.SimpleNamespace]] = {}


def _both(folder: Path) -> tuple[dict, types.SimpleNamespace]:
    stamp = (str(folder.resolve()), max(p.stat().st_mtime for p in folder.iterdir()))
    if stamp not in _TRUTH_CACHE:
        _TRUTH_CACHE[stamp] = _post(folder)
    return _TRUTH_CACHE[stamp]


def _expected(folder: Path) -> dict:
    return _both(folder)[0]


def _facts(folder: Path) -> types.SimpleNamespace:
    return _both(folder)[1]


def _read_json(path: Path) -> object:
    return json.loads(path.read_text(encoding="utf-8"))


def _read_jsonl(path: Path) -> list[dict]:
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line]


def _same(got: object, want: object) -> bool:
    """Equality that compares JSON types as well as values, used wherever the payload
    carries the integer cents, units and counts schema.md asks for. Plain Python
    equality holds for -45562.0 == -45562 and for True == 1, so a float or a boolean
    would stand in for an integer; canonical JSON text keeps them apart."""
    return json.dumps(got, sort_keys=True) == json.dumps(want, sort_keys=True)


def _run_transform(input_dir: Path, output_dir: Path, cap: int = 300) -> dict[str, object]:
    script = OUT_DIR / "transform.py"
    assert script.is_file(), "transform.py missing"
    before = ({p.resolve() for p in output_dir.parent.rglob("*")}
              if output_dir.parent.exists() else set())
    output_dir.parent.mkdir(parents=True, exist_ok=True)
    try:
        output_dir.parent.chmod(0o777)
    except PermissionError:
        pass
    for path in [input_dir, *input_dir.rglob("*")]:
        path.chmod(0o755 if path.is_dir() else 0o644)
    if output_dir.is_dir():
        output_dir.chmod(0o777)
    # An agent editor leaves transform.py at mode 0600 owned by uid 1000, which
    # the dropped uid (setpriv --reuid=nobody) could not read; make it readable
    # and its parents traversable before the drop. The verifier runs as root.
    try:
        script.chmod(0o755)
        for parent in script.parents:
            parent.chmod(parent.stat().st_mode | 0o055)
            if parent == APP_ROOT:
                break
    except OSError:
        pass
    proc = subprocess.Popen(
        _untrusted_command([sys.executable, str(script), str(input_dir), str(output_dir)]),
        text=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE, start_new_session=True)
    try:
        _out, err = proc.communicate(timeout=cap)
    finally:
        try:
            os.killpg(os.getpgid(proc.pid), signal.SIGKILL)
        except (ProcessLookupError, PermissionError, OSError):
            pass
        proc.wait()
    assert proc.returncode == 0, err[-500:]
    after = {p.resolve() for p in output_dir.parent.rglob("*")}
    outside = [p for p in after - before if output_dir.resolve() not in [p, *p.parents]]
    assert not outside, f"wrote outside output dir: {outside}"
    return {name: (_read_jsonl(output_dir / name) if name.endswith(".jsonl")
                   else _read_json(output_dir / name))
            for name in ARTIFACTS if name != "transform.py"}


def _clone_book(target: Path) -> None:
    target.mkdir(parents=True, exist_ok=True)
    for path in _book_dir().iterdir():
        if path.is_file():
            (target / path.name).write_bytes(path.read_bytes())


def _rewrite(path: Path, rows: list[dict], sep: str) -> None:
    with path.open("w", encoding="utf-8", newline="") as fh:
        writer = csv.DictWriter(fh, fieldnames=list(rows[0]), delimiter=sep,
                                lineterminator="\n")
        writer.writeheader()
        writer.writerows(rows)


def _permute(folder: Path, seed: int) -> None:
    """Shuffle the files whose row order the contract leaves free, and move one
    currency's whole rate curve."""
    dice = random.Random(seed)
    for name in ("consumption.csv", "meter_sites.csv", "service_zones.csv",
                 "tariff_catalogue.csv", "collectors.csv", "currency_rates.csv"):
        rows = _grid(folder / name)
        if name == "currency_rates.csv":
            pool = sorted({_trim(r["currency"]).upper() for r in rows} - {"USD", "ZAR"})
            moved = dice.choice(pool)
            for row in rows:
                if _trim(row["currency"]).upper() == moved:
                    row["usd_rate"] = str((Decimal(_trim(row["usd_rate"]))
                                           * Decimal("1.0425")).quantize(Decimal("0.000001")))
        dice.shuffle(rows)
        _rewrite(folder / name, rows, ",")
    tsv = _grid(folder / "remittances.tsv", "\t")
    dice.shuffle(tsv)
    _rewrite(folder / "remittances.tsv", tsv, "\t")
    jsonl = [line for line in (folder / "levies.jsonl")
             .read_text(encoding="utf-8").splitlines() if line.strip()]
    dice.shuffle(jsonl)
    (folder / "levies.jsonl").write_text("".join(line + "\n" for line in jsonl),
                                         encoding="utf-8")
    pipe = (folder / "legacy_reads.txt").read_text(encoding="latin-1").splitlines()
    dice.shuffle(pipe)
    (folder / "legacy_reads.txt").write_text("\n".join(pipe) + "\n", encoding="latin-1")


def _repolicy(folder: Path) -> None:
    text = (folder / "policy.ini").read_text(encoding="utf-8")
    for before, after in POLICY_SHIFT:
        assert before in text, before
        text = text.replace(before, after, 1)
    (folder / "policy.ini").write_text(text, encoding="utf-8")


def _strip_class(folder: Path, tariff_class: str) -> None:
    """Remove every reading booked to an account of one tariff class, so that
    class draws nothing and its segment file has to be written empty anyway.
    An amendment can move a reading onto another account, and the account it
    lands on is the one that decides, so the links are read amended."""
    doomed = {who for who, seat in _Vault(folder).holder.items()
              if seat["tariff_class"] == tariff_class}
    fixes = _fix_table(folder)

    def booked_to(origin: str, ident: str, raw_account: object) -> str:
        if "account_id" in PATCHABLE[origin] and (ident, "account_id") in fixes:
            return _trim(fixes[(ident, "account_id")])
        return _trim(raw_account)

    for name, sep in (("consumption.csv", ","), ("remittances.tsv", "\t")):
        kept = [row for row in _grid(folder / name, sep)
                if booked_to(name, _trim(row.get("reading_id")),
                             row.get("account_id")) not in doomed]
        _rewrite(folder / name, kept, sep)
    levies = []
    for line in (folder / "levies.jsonl").read_text(encoding="utf-8").splitlines():
        if not line.strip():
            continue
        try:
            payload = json.loads(line)
        except ValueError:
            payload = {}
        if booked_to("levies.jsonl", _trim(payload.get("reading_id")),
                     payload.get("account_id")) not in doomed:
            levies.append(line)
    (folder / "levies.jsonl").write_text("".join(line + "\n" for line in levies),
                                         encoding="utf-8")
    pipe = []
    for line in (folder / "legacy_reads.txt").read_text(encoding="latin-1").splitlines():
        cell = [piece.strip() for piece in line.split("|")]
        if len(cell) == 11 and booked_to("legacy_reads.txt", cell[0], cell[2]) in doomed:
            continue
        pipe.append(line)
    (folder / "legacy_reads.txt").write_text("\n".join(pipe) + "\n", encoding="latin-1")


