def _check_output_serialization_is_canonical():
    """POSITIVE: every line of the stream is its own compact sorted serialization and
    every document ends in a newline. Each artifact is re-serialized from what the
    agent wrote, so this reads the shape of the bytes and never their content, which
    normalized_stream_is_exact and the roll-up checks own."""
    raw = (OUT_DIR / "normalized.jsonl").read_text(encoding="utf-8")
    assert raw.endswith("\n")
    lines = raw.splitlines()
    assert lines
    assert lines == [json.dumps(json.loads(line), sort_keys=True, separators=(",", ":"))
                     for line in lines]
    for name in ARTIFACTS:
        if not name.endswith(".json"):
            continue
        body = (OUT_DIR / name).read_text(encoding="utf-8")
        assert body.endswith("\n")
        assert body == json.dumps(json.loads(body), indent=2, sort_keys=True) + "\n"


