def _transform_tree() -> ast.Module:
    return ast.parse((OUT_DIR / "transform.py").read_text(encoding="utf-8"))


def _imported_modules(tree: ast.Module) -> set[str]:
    found: set[str] = set()
    for node in ast.walk(tree):
        if isinstance(node, ast.Import):
            for alias in node.names:
                found.add(alias.name)
                found.add(alias.name.partition(".")[0])
        elif isinstance(node, ast.ImportFrom) and node.module and not node.level:
            found.add(node.module)
            found.add(node.module.partition(".")[0])
            for alias in node.names:
                found.add(f"{node.module}.{alias.name}")
    return found


def _called_names(tree: ast.Module) -> set[str]:
    found: set[str] = set()
    for node in ast.walk(tree):
        if not isinstance(node, ast.Call):
            continue
        if isinstance(node.func, ast.Attribute):
            found.add(node.func.attr)
        elif isinstance(node.func, ast.Name):
            found.add(node.func.id)
    return found


def _check_negative_weight_network_dependency_or_shell_cheat():
    """NEGATIVE: holds when the transform imports a package outside the standard
    library, reaches the network, or spawns a shell."""
    tree = _transform_tree()
    imported = _imported_modules(tree)
    off_the_shelf = {name for name in imported
                     if "." not in name and name not in sys.stdlib_module_names}
    reached_out = imported & (_NETWORK_MODULES | _PROCESS_MODULES)
    shelled_out = _called_names(tree) & _SHELL_CALLS
    assert off_the_shelf or reached_out or shelled_out


def _check_negative_weight_nondeterministic_output():
    """NEGATIVE: holds when two runs over one unchanged book disagree on the bytes
    of an artifact, which is what entropy, a clock read or an unordered set does
    once it reaches the output. The assertion is true only when that happened, so
    a byte stable program leaves it failing and a clock the program never writes
    down costs nothing."""
    book = Path(tempfile.mkdtemp(prefix="meter-twice-in-"))
    _clone_book(book)
    first = Path(tempfile.mkdtemp(prefix="meter-twice-a-")) / "out"
    second = Path(tempfile.mkdtemp(prefix="meter-twice-b-")) / "out"
    _run_transform(book, first, cap=120)
    _run_transform(book, second, cap=120)
    assert any((first / name).read_bytes() != (second / name).read_bytes()
               for name in ARTIFACTS if name != "transform.py")


